class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;
        if (k == 0) {
            return;
        }

        reverse(nums, 0, n - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
    }

    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
            left++;
            right--;
        }
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;

        int[] rotated = new int[n];
        for (int i = 0; i < n; i++) {
            rotated[(i + k) % n] = nums[i];
        }

        System.arraycopy(rotated, 0, nums, 0, n);
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;
        if (k == 0) {
            return;
        }

        int moved = 0;
        for (int start = 0; moved < n; start++) {
            int current = start;
            int previous = nums[start];
            do {
                int next = (current + k) % n;
                int temp = nums[next];
                nums[next] = previous;
                previous = temp;
                current = next;
                moved++;
            } while (current != start);
        }
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k %= n;
        if (k == 0) {
            return;
        }

        int leftRotation = n - k;
        blockSwapLeft(nums, 0, leftRotation, n);
    }

    private void blockSwapLeft(int[] nums, int start, int leftSize, int length) {
        if (leftSize == 0 || leftSize == length) {
            return;
        }

        int rightSize = length - leftSize;
        if (leftSize == rightSize) {
            swapBlocks(nums, start, start + leftSize, leftSize);
        } else if (leftSize < rightSize) {
            swapBlocks(nums, start, start + length - leftSize, leftSize);
            blockSwapLeft(nums, start, leftSize, length - leftSize);
        } else {
            swapBlocks(nums, start, start + leftSize, rightSize);
            blockSwapLeft(nums, start + rightSize, leftSize - rightSize, leftSize);
        }
    }

    private void swapBlocks(int[] nums, int first, int second, int length) {
        for (int i = 0; i < length; i++) {
            int temp = nums[first + i];
            nums[first + i] = nums[second + i];
            nums[second + i] = temp;
        }
    }
}
